import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    # find seed: largest connected non-bg component (by cells)
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or not(0<=y<h and 0<=x<w) or g[y][x]==bg: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1): stack.append((y+dy,x+dx))
                comps.append(comp)
    comps.sort(key=len, reverse=True)
    seed=max(comps,key=len)
    rs=[p[0] for p in seed]; cs=[p[1] for p in seed]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    pat=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    ph,pw=len(pat),len(pat[0])
    out=[row[:] for row in g]
    for comp in comps:
        if comp is seed: continue
        # marker comps: single cells (or small?) - treat every comp not seed as marker
        # decide anchor: try centering pattern bbox on comp bbox
        comps_ = sorted(comps,key=len)
        # markers = smallest comps
        marks=sorted([c for c in comps if c is not seed], key=len)
        for m in marks:
            ms=[p for p in m]
            mr=sum(p[0] for p in ms)/len(ms); mc=sum(p[1] for p in ms)/len(ms)
            ar,ac=int(round(mr-(ph-1)/2)),int(round(mc-(pw-1)/2))
            for i in range(ph):
                for j in range(pw):
                    ny,nx=ar+i,ac+j
                    if 0<=ny<h and 0<=nx<w: out[ny][nx]=pat[i][j]
    return out

